  <article class="container guide-article"><Breadcrumbs :page="page" /><header class="article-header"><p class="eyebrow">PRACTICAL WINDOWS DATA GUIDE</p><h1>{{ page.h1 }}</h1><p class="article-lead">{{ page.description }}</p></header>
